1. [CmdletBinding()]
2. param(
3.     [Parameter(Position = 0)]
4.     [string]$Command = 'help',
5. 
6.     [Parameter(Position = 1, ValueFromRemainingArguments)]
7.     [string[]]$CliArguments = @()
8. )
9. 
10. Set-StrictMode -Version Latest
11. $ErrorActionPreference = 'Stop'
12. Import-Module (Join-Path $PSScriptRoot 'TaskForge.Core.psm1') -Force -WarningAction SilentlyContinue
13. 
14. try {
15.     $commandName = $Command.ToLowerInvariant()
16.     $templateAction = $null
17.     $argumentsToParse = $CliArguments
18.     if ($commandName -eq 'template') {
19.         if ($CliArguments.Count -eq 0 -or $CliArguments[0].StartsWith('--')) {
20.             throw 'Missing template action: save, list, or remove.'
21.         }
22.         $templateAction = $CliArguments[0].ToLowerInvariant()
23.         $argumentsToParse = if ($CliArguments.Count -gt 1) { @($CliArguments[1..($CliArguments.Count - 1)]) } else { @() }
24.     }
25. 
26.     $options = ConvertFrom-TaskForgeArguments -Arguments $argumentsToParse
27.     $defaultDataFile = Join-Path (Split-Path -Parent $PSScriptRoot) 'data/tasks.json'
28.     $dataFile = if ($options.Contains('data-file')) {
29.         Get-RequiredOption -Options $options -Name 'data-file'
30.     }
31.     else {
32.         $defaultDataFile
33.     }
34.     $asJson = $options.Contains('json')
35. 
36.     switch ($commandName) {
37.         'add' {
38.             Assert-KnownOptions -Options $options -Allowed @('title', 'description', 'template', 'data-file', 'json')
39.             $template = $null
40.             if ($options.Contains('template')) {
41.                 $templateName = Get-ValidTemplateName (Get-RequiredOption -Options $options -Name 'template')
42.                 $templates = @(Read-TemplateStore -Path (Get-TemplateStorePath -DataFile $dataFile))
43.                 $template = Find-Template -Templates $templates -Name $templateName
44.                 if ($null -eq $template) {
45.                     throw "Template '$templateName' was not found."
46.                 }
47.             }
48. 
49.             $title = if ($options.Contains('title')) {
50.                 (Get-RequiredOption -Options $options -Name 'title').Trim()
51.             }
52.             elseif ($null -ne $template) {
53.                 [string]$template.title
54.             }
55.             else {
56.                 throw 'Missing required option: --title'
57.             }
58.             $description = if ($options.Contains('description')) {
59.                 Get-OptionValue -Options $options -Name 'description'
60.             }
61.             elseif ($null -ne $template) {
62.                 [string]$template.description
63.             }
64.             else {
65.                 ''
66.             }
67. 
68.             $tasks = @(Read-TaskStore -Path $dataFile)
69.             $nextId = if ($tasks.Count -eq 0) { 1 } else { 1 + [int](($tasks | Measure-Object -Property id -Maximum).Maximum) }
70.             $task = [ordered]@{
71.                 id = $nextId
72.                 title = $title
73.                 description = $description
74.                 status = 'pending'
75.                 createdAt = [DateTimeOffset]::UtcNow.ToString('o')
76.             }
77.             Write-TaskStore -Path $dataFile -Tasks @($tasks + [pscustomobject]$task)
78.             if ($asJson) {
79.                 Write-TaskForgeOutput -Value ([pscustomobject]$task) -AsJson $true
80.             }
81.             else {
82.                 "Added task ${nextId}: $($task.title)"
83.             }
84.         }
85.         'list' {
86.             Assert-KnownOptions -Options $options -Allowed @('data-file', 'json')
87.             $tasks = @(Read-TaskStore -Path $dataFile | Sort-Object { [int]$_.id })
88.             if ($asJson) {
89.                 Write-TaskForgeOutput -Value $tasks -AsJson $true
90.             }
91.             elseif ($tasks.Count -eq 0) {
92.                 'No tasks.'
93.             }
94.             else {
95.                 $tasks | ForEach-Object { "[{0}] #{1} {2}" -f $_.status, $_.id, $_.title }
96.             }
97.         }
98.         'complete' {
99.             Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'json')
100.             $idText = Get-RequiredOption -Options $options -Name 'id'
101.             $id = 0
102.             if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
103.                 throw '--id must be a positive integer.'
104.             }
105.             $tasks = @(Read-TaskStore -Path $dataFile)
106.             $task = $tasks | Where-Object { [int]$_.id -eq $id } | Select-Object -First 1
107.             if ($null -eq $task) {
108.                 throw "Task $id was not found."
109.             }
110.             $task.status = 'completed'
111.             Write-TaskStore -Path $dataFile -Tasks $tasks
112.             if ($asJson) {
113.                 Write-TaskForgeOutput -Value $task -AsJson $true
114.             }
115.             else {
116.                 "Completed task $id."
117.             }
118.         }
119.         'remove' {
120.             Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'json')
121.             $idText = Get-RequiredOption -Options $options -Name 'id'
122.             $id = 0
123.             if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
124.                 throw '--id must be a positive integer.'
125.             }
126.             $tasks = @(Read-TaskStore -Path $dataFile)
127.             $remaining = @($tasks | Where-Object { [int]$_.id -ne $id })
128.             if ($remaining.Count -eq $tasks.Count) {
129.                 throw "Task $id was not found."
130.             }
131.             Write-TaskStore -Path $dataFile -Tasks $remaining
132.             $summary = [pscustomobject]@{ removedId = $id }
133.             if ($asJson) {
134.                 Write-TaskForgeOutput -Value $summary -AsJson $true
135.             }
136.             else {
137.                 "Removed task $id."
138.             }
139.         }
140.         'template' {
141.             $templateStore = Get-TemplateStorePath -DataFile $dataFile
142.             switch ($templateAction) {
143.                 'save' {
144.                     Assert-KnownOptions -Options $options -Allowed @('name', 'title', 'description', 'data-file', 'json')
145.                     $name = Get-ValidTemplateName (Get-RequiredOption -Options $options -Name 'name')
146.                     $title = (Get-RequiredOption -Options $options -Name 'title').Trim()
147.                     $description = if ($options.Contains('description')) {
148.                         Get-OptionValue -Options $options -Name 'description'
149.                     }
150.                     else {
151.                         ''
152.                     }
153.                     $templates = @(Read-TemplateStore -Path $templateStore)
154.                     if ($null -ne (Find-Template -Templates $templates -Name $name)) {
155.                         throw "Template '$name' already exists."
156.                     }
157.                     $template = [pscustomobject][ordered]@{
158.                         name = $name
159.                         title = $title
160.                         description = $description
161.                     }
162.                     Write-TemplateStore -Path $templateStore -Templates @($templates + $template)
163.                     if ($asJson) {
164.                         Write-TaskForgeOutput -Value $template -AsJson $true
165.                     }
166.                     else {
167.                         Write-TemplateBanner
168.                         "Saved template '$name'."
169.                     }
170.                 }
171.                 'list' {
172.                     Assert-KnownOptions -Options $options -Allowed @('data-file', 'json')
173.                     $templates = @(Read-TemplateStore -Path $templateStore |
174.                         Sort-Object @{ Expression = { [string]$_.name }; Ascending = $true })
175.                     if ($asJson) {
176.                         Write-TaskForgeOutput -Value $templates -AsJson $true
177.                     }
178.                     else {
179.                         Write-TemplateBanner
180.                         if ($templates.Count -eq 0) {
181.                             'No templates.'
182.                         }
183.                         else {
184.                             $templates | ForEach-Object {
185.                                 if ([string]::IsNullOrEmpty([string]$_.description)) {
186.                                     "$($_.name): $($_.title)"
187.                                 }
188.                                 else {
189.                                     "$($_.name): $($_.title) - $($_.description)"
190.                                 }
191.                             }
192.                         }
193.                     }
194.                 }
195.                 'remove' {
196.                     Assert-KnownOptions -Options $options -Allowed @('name', 'data-file', 'json')
197.                     $name = Get-ValidTemplateName (Get-RequiredOption -Options $options -Name 'name')
198.                     $templates = @(Read-TemplateStore -Path $templateStore)
199.                     $template = Find-Template -Templates $templates -Name $name
200.                     if ($null -eq $template) {
201.                         throw "Template '$name' was not found."
202.                     }
203.                     $remaining = @($templates | Where-Object {
204.                         -not [string]::Equals([string]$_.name, $name, [System.StringComparison]::OrdinalIgnoreCase)
205.                     })
206.                     Write-TemplateStore -Path $templateStore -Templates $remaining
207.                     $summary = [pscustomobject]@{ removedName = [string]$template.name }
208.                     if ($asJson) {
209.                         Write-TaskForgeOutput -Value $summary -AsJson $true
210.                     }
211.                     else {
212.                         Write-TemplateBanner
213.                         "Removed template '$($template.name)'."
214.                     }
215.                 }
216.                 default {
217.                     throw "Unknown template action: $templateAction"
218.                 }
219.             }
220.         }
221.         'help' {
222.             Assert-KnownOptions -Options $options -Allowed @()
223.             @'
224. TaskForge
225.   add [--template NAME] [--title TEXT] [--description TEXT] [--data-file PATH] [--json]
226.   list [--data-file PATH] [--json]
227.   complete --id ID [--data-file PATH] [--json]
228.   remove --id ID [--data-file PATH] [--json]
229.   template save --name NAME --title TEXT [--description TEXT] [--data-file PATH] [--json]
230.   template list [--data-file PATH] [--json]
231.   template remove --name NAME [--data-file PATH] [--json]
232. '@
233.         }
234.         default {
235.             throw "Unknown command: $Command"
236.         }
237.     }
238. }
239. catch {
240.     [Console]::Error.WriteLine("TaskForge: $($_.Exception.Message)")
241.     exit 1
242. }
243.

